using System.Data;using System.Data.Common;using AiCare.Application;using AiCare.Domain;using AiCare.Infrastructure;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AiCare.Api;
[ApiController][Authorize(Policy="Phase1User")][Route("api/phase1/complaints")]
public sealed class ComplaintGovernanceController(CareDbContext db,ITenantContext tenant,ICurrentUserContext user):ControllerBase{
[HttpGet][Authorize(Roles="CareCoordinator,CareManager,Administrator")]
public async Task<IActionResult> Cases([FromQuery]string? status,CancellationToken t)=>Ok(await QueryCases("organization_id=@organization and branch_id=coalesce(@branch,branch_id) and status=coalesce(@status,status)",c=>Add(c,"status",status),t));
[HttpGet("mine")]
public async Task<IActionResult> Mine(CancellationToken t){var familyId=user.FamilyMemberId;if(familyId is null)familyId=await db.AppUsers.AsNoTracking().Where(x=>x.OrganizationId==tenant.OrganizationId&&x.FamilyMemberId!=null&&((user.UserId!=null&&x.Id==user.UserId)||x.UserName==user.UserName)).Select(x=>x.FamilyMemberId).SingleOrDefaultAsync(t);if(familyId is null)return Forbid();var cases=await QueryCases("organization_id=@organization and family_member_id=@family",c=>Add(c,"family",familyId.Value),t);foreach(var item in cases)item.History=await Events(item.Id,true,t);return Ok(cases);}
[HttpGet("alerts")][Authorize(Roles="CareCoordinator,CareManager,Administrator")]
public async Task<IActionResult> Alerts(CancellationToken t){var rows=await QueryCases("organization_id=@organization and branch_id=coalesce(@branch,branch_id) and status not in ('Closed','Resolved') and response_due_at<now()",_=>{},t);return Ok(rows);}
[HttpPatch("{id:guid}/assign")][Authorize(Roles="CareCoordinator,CareManager,Administrator")]
public async Task<IActionResult> Assign(Guid id,AssignComplaintRequest request,CancellationToken t){var row=await Case(id,t);if(row is null)return NotFound();if(string.IsNullOrWhiteSpace(request.AssignedTo)||request.ResponseDueAt<=DateTimeOffset.UtcNow)return BadRequest(new{message="Assignee and future response deadline are required."});await Execute("update family_feedback_cases set assigned_to=@owner,response_due_at=@due where id=@id and organization_id=@organization",c=>{Add(c,"owner",request.AssignedTo.Trim());Add(c,"due",request.ResponseDueAt);Add(c,"id",id);},t);await Event(id,"Assigned",$"Assigned to {request.AssignedTo}; response due {request.ResponseDueAt:u}.",false,t);Audit("complaint.assigned",id);await db.SaveChangesAsync(t);return NoContent();}
[HttpPost("{id:guid}/transition")][Authorize(Roles="CareCoordinator,CareManager,Administrator")]
public async Task<IActionResult> Transition(Guid id,ComplaintTransitionRequest request,CancellationToken t){var row=await Case(id,t);if(row is null)return NotFound();var action=request.Action?.Trim()??"";string next;string sql;bool visible=false;switch(action){case"Acknowledge":if(string.IsNullOrWhiteSpace(row.AssignedTo))return Conflict(new{message="Assign the complaint before acknowledgement."});next="Acknowledged";sql="update family_feedback_cases set status=@status,acknowledged_at=now() where id=@id and organization_id=@organization";visible=true;break;case"StartReview":next="InReview";sql="update family_feedback_cases set status=@status where id=@id and organization_id=@organization";break;case"Respond":if(string.IsNullOrWhiteSpace(request.InvestigationSummary)||string.IsNullOrWhiteSpace(request.ResponseText))return BadRequest(new{message="Investigation summary and response are required."});next="Responded";sql="update family_feedback_cases set status=@status,investigation_summary=@investigation,response_text=@response,responded_at=now() where id=@id and organization_id=@organization";visible=true;break;case"Resolve":if(string.IsNullOrWhiteSpace(row.ResponseText)&&string.IsNullOrWhiteSpace(request.ResponseText))return Conflict(new{message="A response is required before resolution."});if(string.IsNullOrWhiteSpace(request.Resolution))return BadRequest(new{message="Resolution is required."});next="Resolved";sql="update family_feedback_cases set status=@status,resolution=@resolution,resolved_at=now() where id=@id and organization_id=@organization";visible=true;break;case"Close":if(!user.IsCareManager&&!user.IsAdministrator)return Forbid();if(row.Status!="Resolved")return Conflict(new{message="Only resolved complaints can be closed."});if(string.IsNullOrWhiteSpace(request.ClosureSummary))return BadRequest(new{message="Closure summary is required."});next="Closed";sql="update family_feedback_cases set status=@status,closure_summary=@closure,closed_at=now(),resolution_approved_by=@actor where id=@id and organization_id=@organization";visible=true;break;case"Reopen":if(!user.IsCareManager&&!user.IsAdministrator)return Forbid();if(row.Status!="Closed")return Conflict(new{message="Only closed complaints can be reopened."});if(string.IsNullOrWhiteSpace(request.Reason))return BadRequest(new{message="Reopening reason is required."});next="InReview";sql="update family_feedback_cases set status=@status,closed_at=null,closure_summary='' where id=@id and organization_id=@organization";visible=true;break;default:return BadRequest(new{message="Unsupported complaint transition."});}await Execute(sql,c=>{Add(c,"status",next);Add(c,"id",id);Add(c,"investigation",request.InvestigationSummary?.Trim()??"");Add(c,"response",request.ResponseText?.Trim()??"");Add(c,"resolution",request.Resolution?.Trim()??"");Add(c,"closure",request.ClosureSummary?.Trim()??"");Add(c,"actor",user.UserName);},t);await Event(id,action,request.ResponseText??request.Resolution??request.ClosureSummary??request.Reason??action,visible,t);Audit($"complaint.{action.ToLowerInvariant()}",id);await db.SaveChangesAsync(t);return NoContent();}
private async Task<ComplaintResponse?> Case(Guid id,CancellationToken t)=>(await QueryCases("id=@id and organization_id=@organization and branch_id=coalesce(@branch,branch_id)",c=>Add(c,"id",id),t)).SingleOrDefault();
private async Task<List<ComplaintResponse>> QueryCases(string where,Action<DbCommand> bind,CancellationToken t){var rows=new List<ComplaintResponse>();await using var c=await Command($"select id,service_user_id,family_member_id,type,subject,description,priority,status,submitted_at,assigned_to,response_due_at,investigation_summary,response_text,responded_at,resolution,resolved_at,closure_summary,closed_at,resolution_approved_by from family_feedback_cases where {where} order by submitted_at desc",t);bind(c);await using var r=await c.ExecuteReaderAsync(t);while(await r.ReadAsync(t))rows.Add(new(r.GetGuid(0),r.GetGuid(1),r.GetGuid(2),r.GetString(3),r.GetString(4),r.GetString(5),r.GetString(6),r.GetString(7),Date(r,8)!.Value,r.GetString(9),Date(r,10),r.GetString(11),r.GetString(12),Date(r,13),r.GetString(14),Date(r,15),r.GetString(16),Date(r,17),r.GetString(18),[]));return rows;}
private async Task<List<ComplaintEventResponse>> Events(Guid id,bool family,CancellationToken t){var rows=new List<ComplaintEventResponse>();await using var c=await Command("select id,event_type,detail,actor,occurred_at from complaint_case_events where case_id=@id and organization_id=@organization and (@family=false or visible_to_family) order by occurred_at",t);Add(c,"id",id);Add(c,"family",family);await using var r=await c.ExecuteReaderAsync(t);while(await r.ReadAsync(t))rows.Add(new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetString(3),Date(r,4)!.Value));return rows;}
private Task Event(Guid id,string type,string detail,bool visible,CancellationToken t)=>Execute("insert into complaint_case_events(id,case_id,organization_id,branch_id,event_type,detail,visible_to_family,actor) values(@event,@id,@organization,@branch,@type,@detail,@visible,@actor)",c=>{Add(c,"event",Guid.NewGuid());Add(c,"id",id);Add(c,"type",type);Add(c,"detail",detail);Add(c,"visible",visible);Add(c,"actor",user.UserName);},t);
private void Audit(string action,Guid id)=>db.AuditEvents.Add(new AuditEvent(Guid.NewGuid(),action,user.UserName,"Complaint",id,DateTimeOffset.UtcNow,tenant.OrganizationId,tenant.BranchId??TenantDefaults.BranchId));private async Task<int> Execute(string sql,Action<DbCommand> bind,CancellationToken t){await using var c=await Command(sql,t);bind(c);return await c.ExecuteNonQueryAsync(t);}private async Task<DbCommand> Command(string sql,CancellationToken t){var connection=db.Database.GetDbConnection();if(connection.State!=ConnectionState.Open)await connection.OpenAsync(t);var c=connection.CreateCommand();c.CommandText=sql;Add(c,"organization",tenant.OrganizationId);Add(c,"branch",tenant.BranchId);return c;}private static DateTimeOffset? Date(DbDataReader r,int i)=>r.IsDBNull(i)?null:r.GetFieldValue<DateTimeOffset>(i);private static void Add(DbCommand c,string n,object? v){if(c.Parameters.Contains(n))return;var p=c.CreateParameter();p.ParameterName=n;p.Value=v??DBNull.Value;c.Parameters.Add(p);}}
public sealed record AssignComplaintRequest(string AssignedTo,DateTimeOffset ResponseDueAt);public sealed record ComplaintTransitionRequest(string Action,string? InvestigationSummary,string? ResponseText,string? Resolution,string? ClosureSummary,string? Reason);public sealed record ComplaintEventResponse(Guid Id,string EventType,string Detail,string Actor,DateTimeOffset OccurredAt);public sealed record ComplaintResponse(Guid Id,Guid ServiceUserId,Guid FamilyMemberId,string Type,string Subject,string Description,string Priority,string Status,DateTimeOffset SubmittedAt,string AssignedTo,DateTimeOffset? ResponseDueAt,string InvestigationSummary,string ResponseText,DateTimeOffset? RespondedAt,string Resolution,DateTimeOffset? ResolvedAt,string ClosureSummary,DateTimeOffset? ClosedAt,string ResolutionApprovedBy,List<ComplaintEventResponse> History){public List<ComplaintEventResponse> History{get;set;}=History;}
